pub const DROP_TILT_SCALE: f64 = 0.7;

pub fn get_shape_data(shape: ShapeKind) -> ShapeData {
    match shape {
        ShapeKind::Blob => ShapeData {
            ring: &BLOB_RING,
            face: BLOB_FACE,
            tilt_scale: BLOB_TILT_SCALE,
        },
        ShapeKind::Wedge => ShapeData {
            ring: &WEDGE_RING,
            face: WEDGE_FACE,
            tilt_scale: WEDGE_TILT_SCALE,
        },
        ShapeKind::Gem => ShapeData {
            ring: &GEM_RING,
            face: GEM_FACE,
            tilt_scale: GEM_TILT_SCALE,
        },
        ShapeKind::Star => ShapeData {
            ring: &STAR_RING,
            face: STAR_FACE,
            tilt_scale: STAR_TILT_SCALE,
        },
        ShapeKind::Cloud => ShapeData {
            ring: &CLOUD_RING,
            face: CLOUD_FACE,
            tilt_scale: CLOUD_TILT_SCALE,
        },
        ShapeKind::Heart => ShapeData {
            ring: &HEART_RING,
            face: HEART_FACE,
            tilt_scale: HEART_TILT_SCALE,
        },
        ShapeKind::Square => ShapeData {
            ring: &SQUARE_RING,
            face: SQUARE_FACE,
            tilt_scale: SQUARE_TILT_SCALE,
        },
        ShapeKind::Drop => ShapeData {
            ring: &DROP_RING,
            face: DROP_FACE,
            tilt_scale: DROP_TILT_SCALE,
        },
        ShapeKind::Whale => ShapeData {
            ring: &crate::extra_shapes::WHALE_RING,
            face: crate::extra_shapes::WHALE_FACE,
            tilt_scale: crate::extra_shapes::WHALE_TILT_SCALE,
        },
        ShapeKind::Cat => ShapeData {
            ring: &crate::extra_shapes::CAT_RING,
            face: crate::extra_shapes::CAT_FACE,
            tilt_scale: crate::extra_shapes::CAT_TILT_SCALE,
        },
    }
}
